def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remainder = np.mod(bins, item)
    penalty = 0.01 * (bins - item)  # Penalty proportional to remaining capacity after placement
    score = -remainder - penalty
    return np.where(bins >= item, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remainder = np.mod(bins, item)
    return np.where(bins >= item, -remainder, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_cap = bins - item
    return np.where(remaining_cap >= 0, -remaining_cap, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    bin_indices = np.arange(len(bins))
    return np.where(bins >= item, -bin_indices, -np.inf)
